// Generic variables
uint32_t anim_timer;                        // timer used to track time before going idle/sleep
uint32_t frame_timer;                       // timer used to pace frametime of idle/sleep animations
uint8_t  bongo_current_tap_frame  = 0;      // counter to go between frames of a tap animation
uint8_t  bongo_current_idle_frame = 0;      // counter to go between frames of a idle animation
bool     bongo_tapped             = false;  // flag set to true by qmk when a key is pressed, used to display tap animations
uint8_t  bongo_animation          = 0;      // used to cycle through hiding/blush/caps animations
bool     caps_lock_on;
uint8_t  mods_state;

void print_text(void) {
    uint8_t highest_layer = get_highest_layer(layer_state);

    oled_set_cursor(19, 2);
    if (highest_layer > 0) {
        oled_write_P(PSTR("L"), false);
        oled_write_char(highest_layer + 0x30, false);
    } else {
        oled_write_P(PSTR("  "), false);
    }

    oled_set_cursor(0, 2);
    if (caps_lock_on) {
        oled_write_P(PSTR("CAPS"), false);
    } else {
        oled_write_P(PSTR("    "), false);
    }

    for (uint8_t i = 0; i < BONGO_ANIMATIONS; i++) {
        oled_write_pixel(OLED_DISPLAY_WIDTH -1 - 2 * i, OLED_DISPLAY_HEIGHT - 1, i < bongo_animation);
    }
}

void animate_idle(void) {
    if (timer_elapsed32(frame_timer) > BONGO_IDLE_FRAME_DURATION) {
        frame_timer = timer_read32();
        bongo_current_idle_frame = (bongo_current_idle_frame + 1) % BONGO_IDLE_FRAMES;
        oled_write_raw_P(bongo_idle[bongo_current_idle_frame], DEFAULT_ANIM_SIZE);
    }
}

void animate_sleep(void) {
    if (timer_elapsed32(frame_timer) > BONGO_SLEEP_FRAME_DURATION) {
        frame_timer = timer_read32();
        bongo_current_idle_frame = (bongo_current_idle_frame + 1) % BONGO_SLEEP_FRAMES;
        oled_write_raw_P(bongo_sleep[bongo_current_idle_frame], DEFAULT_ANIM_SIZE);
    }
}

bool is_animation_hiding(void) {
    return (mods_state & MOD_MASK_CTRL) || bongo_animation == 1;
}

bool is_animation_blushing(void) {
    return (mods_state & MOD_MASK_ALT) || bongo_animation == 2;
}

bool is_animation_caps(void) {
    return caps_lock_on || bongo_animation == 3;
}

static void draw_bongo(void) {
    mods_state = get_mods();
    caps_lock_on = host_keyboard_led_state().caps_lock;

    if (bongo_tapped) {
        // right after a key is tapped, a tap frame is played
        bongo_tapped = false;
        anim_timer = timer_read32();
        bongo_current_tap_frame = (bongo_current_tap_frame + 1) % BONGO_TAP_FRAMES;
        if (is_animation_hiding()) {
            oled_write_raw_P(bongo_hiding_tap[bongo_current_tap_frame], DEFAULT_ANIM_SIZE);
        } else if (is_animation_blushing()) {
            oled_write_raw_P(bongo_blushing_tap[bongo_current_tap_frame], DEFAULT_ANIM_SIZE);
        } else if (is_animation_caps()) {
            oled_write_raw_P(bongo_caps[1], DEFAULT_ANIM_SIZE);
        } else {
            oled_write_raw_P(bongo_tap[bongo_current_tap_frame], DEFAULT_ANIM_SIZE);
        }
    } else {
        // when no key is pressed, check for alternate animations to be used as idle
        if (is_animation_hiding()) {
            oled_write_raw_P(bongo_hiding[0], DEFAULT_ANIM_SIZE);
        } else if (is_animation_blushing()) {
            oled_write_raw_P(bongo_blushing[0], DEFAULT_ANIM_SIZE);
        } else if (is_animation_caps()) {
            oled_write_raw_P(bongo_caps[0], DEFAULT_ANIM_SIZE);
        }
    }
    
    // if no alternate animation is used, prep then idle then sleep based on the anim_timer
    if (!is_animation_hiding() && !is_animation_blushing() && !is_animation_caps()) {
        uint32_t time_elapsed = timer_elapsed32(anim_timer);
        if (time_elapsed > SLEEP_TIMEOUT) {
            animate_sleep();
        } else if (time_elapsed > IDLE_TIMEOUT) {
            animate_idle();
        } else if (time_elapsed > 100) {
            oled_write_raw_P(bongo_prep[0], DEFAULT_ANIM_SIZE);
        }
    }

    print_text();
}
